package cn.huankan.event;
import java.util.*;import java.time.*;import cn.huankan.evidence.EvidenceService;import cn.huankan.collector.GleifService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;
@Service public class RelationAssessmentService {private final JdbcTemplate db;private final ObjectMapper json;public RelationAssessmentService(JdbcTemplate d,ObjectMapper j){db=d;json=j;}@Transactional public Object audit(){var results=new ArrayList<Map<String,Object>>();for(var r:db.queryForList("SELECT e.*,g.child_lei,g.parent_lei,g.kind,g.details,ga.lei child_identifier,gb.lei parent_identifier,a.official_name child_name,b.official_name parent_name,ga.jurisdiction child_country,gb.jurisdiction parent_country,v.raw_content,v.raw_content_hash,v.published_at,v.collected_at,v.source_url FROM entity_relation e JOIN gleif_level2 g ON g.evidence_id=e.evidence_id JOIN raw_evidence v ON v.id=g.evidence_id JOIN financial_entity a ON a.id=e.subject_id JOIN financial_entity b ON b.id=e.object_id LEFT JOIN LATERAL (SELECT lei,jurisdiction FROM gleif_legal_record WHERE entity_id=a.id ORDER BY last_update DESC NULLS LAST LIMIT 1) ga ON true LEFT JOIN LATERAL (SELECT lei,jurisdiction FROM gleif_legal_record WHERE entity_id=b.id ORDER BY last_update DESC NULLS LAST LIMIT 1) gb ON true ORDER BY e.id LIMIT 100")){try{var detail=json.readTree(r.get("details").toString()).path("attributes");var relation=detail.path("relationship");var checks=new LinkedHashMap<String,Object>();checks.put("child_lei",r.get("child_lei"));checks.put("parent_lei",r.get("parent_lei"));checks.put("legal_names",List.of(r.get("child_name"),r.get("parent_name")));checks.put("jurisdictions",List.of(Objects.toString(r.get("child_country"),"未知"),Objects.toString(r.get("parent_country"),"未知")));checks.put("exact_nodes",r.get("child_lei").equals(relation.path("startNode").path("id").asText())&&r.get("parent_lei").equals(relation.path("endNode").path("id").asText())&&r.get("child_lei").equals(r.get("child_identifier"))&&r.get("parent_lei").equals(r.get("parent_identifier")));checks.put("lei_checks",GleifService.validLei(r.get("child_lei").toString())&&GleifService.validLei(r.get("parent_lei").toString()));checks.put("relationship_type",relation.path("type").asText());checks.put("active",relation.path("status").asText().equals("ACTIVE"));checks.put("periods",relation.path("periods"));checks.put("record_valid_from",detail.path("validFrom"));checks.put("record_valid_until",detail.path("validTo"));checks.put("registration",detail.path("registration"));checks.put("hash_passed",EvidenceService.hash((byte[])r.get("raw_content")).equals(r.get("raw_content_hash")));checks.put("first_public_at",r.get("published_at"));checks.put("source_url",r.get("source_url"));checks.put("collected_at",r.get("collected_at"));boolean expired=!Boolean.TRUE.equals(checks.get("active"));String until=detail.path("validTo").asText("");if(!until.isEmpty())expired|=Instant.parse(until).isBefore(Instant.now());String result=!Boolean.TRUE.equals(checks.get("hash_passed"))||!Boolean.TRUE.equals(checks.get("exact_nodes"))||!Boolean.TRUE.equals(checks.get("lei_checks"))?"INSUFFICIENT":expired?"EXPIRED":r.get("status").equals("REJECTED")?"REJECTED":r.get("status").equals("VERIFIED")?"CONFIRMED":"INSUFFICIENT";String limitations="自动证据审计，未进行人工确认；会计合并不等同供应链、产品采购或持股比例；缺少可验证首次公开时间，不能接受为时点已确认关系；ENTITY_SUPPLIED_ONLY不是独立共证";db.update("INSERT INTO relation_assessment(relation_id,method,rule_version,assessment,evidence_id,checks,limitations) VALUES(?,'AUTOMATED_EVIDENCE_AUDIT','GLEIF关系核对-1.0',?,?,?::jsonb,?)",r.get("id"),result,r.get("evidence_id"),json.writeValueAsString(checks),limitations);results.add(Map.of("relation_id",r.get("id"),"assessment",result,"checks",checks,"limitations",limitations));}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalArgumentException("GLEIF关系核对失败",e);}}return results;}public Object history(){var rows=db.queryForList("SELECT * FROM relation_assessment ORDER BY assessed_at DESC,id DESC LIMIT 100");for(var r:rows)try{r.put("checks",json.readTree(r.get("checks").toString()));}catch(Exception e){throw new IllegalArgumentException("关系审计记录异常");}return rows;}}
